 1 | // SPDX-License-Identifier: MIT
 2 | pragma solidity 0.8.4;
 3 | import "./Governable.sol";
 4 | import "hardhat/console.sol";
 5 | import "../facades/Burnable.sol";
 6 | 
 7 | ///@title Flash Governance Arbiter
 8 | ///@author Justin Goro
 9 | /**@notice LimboDAO offers two forms of governance: flash and proposal. Proposals are contracts that have authorization to execute guarded functions on contracts that implement the Governable abstract contract.
10 |  * Proposals require Fate to be put forward for voting and Fate is the spendable voting token.
11 |  * Flash governance occurs in the duration of one transaction and is more appropriate for variable tweaking such as changing the Flan per Second or Threshold of a pool.
12 |  * Flash governance requires an asset be deposited into an adjudication contract. The community can then vote, through a proposal, whether the decision was legitimate. If not, the deposit can be slashed
13 |  * By default, the asset is EYE.
14 |  */
15 | contract FlashGovernanceArbiter is Governable {
16 |   /**
17 |    * @param actor user making flash governance decision
18 |    * @param deposit_asset is the asset type put up as decision collateral. Must be burnable.
19 |    * @param amount is the amount of the deposit_asset to be put up as decision collateral.
20 |    * @param target is the contract that will be affected by the flash governance decision.
21 |    */
22 |   event flashDecision(address actor, address deposit_asset, uint256 amount, address target);
23 | 
24 |   mapping(address => bool) enforceLimitsActive;
25 | 
26 |   constructor(address dao) Governable(dao) {}
27 | 
28 |   struct FlashGovernanceConfig {
29 |     address asset;
30 |     uint256 amount;
31 |     uint256 unlockTime;
32 |     bool assetBurnable;
33 |   }
34 | 
35 |   //Note: epoch settings prevent DOS attacks. Change tolerance curtails the damage of bad flash governance.
36 |   struct SecurityParameters {
37 |     uint8 maxGovernanceChangePerEpoch; //prevents flash governance from wrecking the incentives.
38 |     uint256 epochSize; //only one flash governance action can happen per epoch to prevent governance DOS
39 |     uint256 lastFlashGovernanceAct;
40 |     uint8 changeTolerance; //1-100 maximum percentage any numeric variable can be changed through flash gov
41 |   }
42 | 
43 |   //the current parameters determining the rules of flash governance
44 |   FlashGovernanceConfig public flashGovernanceConfig;
45 |   SecurityParameters public security;
46 | 
47 |   /*For every decision, we record the config at the time of the decision. This allows governance to change the rules
48 |    *without undermining the terms under which pending decisions were made.
49 |    */
50 |   mapping(address => mapping(address => FlashGovernanceConfig)) public pendingFlashDecision; //contract->user->config
51 | 
52 |   /**
53 |    *@notice An attempt is made to withdraw the current deposit requirement.
54 |    * For a given user, flash governance decisions can only happen one at a time
55 |    *@param sender is the user making the flash governance decision
56 |    *@param target is the contract that will be affected by the flash governance decision.
57 |    *@param emergency flash governance decisions are restricted in frequency per epoch but some decisions are too important. These can be marked emergency.
